+		flex-wrap: wrap;
+	}
+}
+
 .happiness-support.is-placeholder {
 	.happiness-support__heading,
 	.happiness-support__text {
@@ -12,7 +20,7 @@
 		width: 82%;
 	}

-	.happiness-support__illustration {
