 		display: none;
 	}

@@ -29,42 +37,44 @@
 	font-size: 21px;
 }

-.happiness-support__text {
+.happiness-support__description {
 	color: var( --color-text-subtle );
 	margin-bottom: 16px;
 	margin-top: 16px;
 }

-.happiness-support__illustration {
-	float: right;
-	width: 150px;
-	margin-left: 30px;
-	text-align: center;
+.happiness-support__image {
+	flex-shrink: 0;
+	margin: 0 auto;
+	width: 128px;

-	@include breakpoint( '<660px' ) {
-		width: 68px;
+	@include breakpoint( '>660px' ) {
+		width: 178px;
 	}
 }

-.happiness-support__buttons {
-	clear: both;
+.happiness-support__icon {
+	margin-bottom: 20px;

-	@include breakpoint( '<660px' ) {
-		margin-top: 6px;
-		text-align: center;
+	@include breakpoint( '>660px' ) {
+		width: 150px;
+		margin: 0 auto;
 	}
+}
+
+.happiness-support__buttons {
+	width: 100%;

 	.button {
 		@include breakpoint( '<660px' ) {
-			margin-top: 10px;
 			width: 80%;
 		}

 		@include breakpoint( '>660px' ) {
-			margin-top: 10px;

 			&:first-of-type {
 				margin-right: 16px;
+				margin-bottom: 6px;
 			}
 		}
 	}
@@ -72,5 +82,9 @@
 	.happiness-support__support-button {
 		padding-bottom: 11px;
 		padding-top: 2px;
+
+		@include breakpoint( '<660px' ) {
+			margin-top: 16px;
+		}
 	}
 }
